public interface JobExecutionListener {
    void beforeJob(JobExecution jobExecution);
    void afterJob(JobExecution jobExecution);
}

@Component
public class CleanupListener implements JobExecutionListener {

    @Override
    public void beforeJob(JobExecution je) {
        System.out.println("Job starting: Cleanup or Setup here");
    }

    @Override
    public void afterJob(JobExecution je) {
        if (je.getStatus() == BatchStatus.COMPLETED) {
            System.out.println("Job completed successfully!");
        } else if (je.getStatus() == BatchStatus.FAILED) {
            System.out.println("Job failed! Send alert or rollback.");
        }
    }
}

@Bean
public Job sampleJob() {
    return jobBuilderFactory.get("sampleJob")
            .listener(new CleanupListener())
            .start(step1())
            .build();
}

public interface StepExecutionListener extends StepListener {
    void beforeStep(StepExecution stepExecution);
    ExitStatus afterStep(StepExecution stepExecution);
}

public interface ChunkListener extends StepListener {
    void beforeChunk();
    ExitStatus afterChunk();
}

public interface SkipListener<T, S> extends StepListener {
    void onSkipInRead(Throwable t);
    void onSkipInProcess(T item, Throwable t);
    void onSkipInWrite(S item, Throwable t);
}

public interface ItemProcessListener<T, S> {
    void beforeProcess(T item);
    void afterProcess(T item, S result);
    void onProcessError(T item, Exception e);
}

public interface ItemReadListener<T> {
    void beforeRead();
    void afterRead(T item);
    void onReadError(Exception e);
}

public interface ItemWriteListener<S> {
    void beforeWrite(List<? extends S> items);
    void afterWrite(List<? extends S> items);
    void onWriteError(Exception e, List<? extends S> items);
}

public interface RepeatListener {
    void before(RepeatContext context);
    void after(RepeatContext context, RepeatStatus result);
    void open(RepeatContext context);
    void onError(RepeatContext context, Throwable e);
    void close(RepeatContext context);
}

public interface RetryListener {
    <T> void open(RetryContext ctx, RetryCallback<T> callback);
    <T> void onError(RetryContext ctx, RetryCallback<T> callback, Throwable e);
    <T> void close(RetryContext ctx, RetryCallback<T> callback, Throwable e);
}

@Bean
public RetryListener loggingRetryListener() {
    return new RetryListener() {
        @Override
        public <T> void onError(RetryContext ctx, RetryCallback<T> callback, Throwable e) {
            System.out.println("Retry failed, attempt: " + ctx.getRetryCount());
        }
    };
}

